import ast,inspect,pathlib
m=ast.parse(pathlib.Path('examples/chat_console.py').read_text())
for c in m.body:
 if isinstance(c,ast.ClassDef) and c.name in ('Streamer_basic','Streamer_rich'):
  f=next(x for x in c.body if isinstance(x,ast.FunctionDef) and x.name=='stream')
  names=[a.arg for a in f.args.args]
  for label,ns in [('parent',names),('patched',names[:-1]+['think_tag',names[-1]])]:
   sig=inspect.Signature([inspect.Parameter(n,inspect.Parameter.POSITIONAL_OR_KEYWORD) for n in ns])
   try: sig.bind(None,'text','<think>','</think>'); result='accepted'
   except TypeError as e: result=str(e)
   print(c.name,label,result)
